/** $CHROME_PATH wins, then the usual PATH names; null when nothing exists. */
export function chromeBinary(): string | null {
  const env = process.env.CHROME_PATH;
  if (env && fs.existsSync(env)) return env;
  for (const name of PATH_NAMES) {
    for (const dir of (process.env.PATH ?? '').split(':')) {
      if (!dir) continue;
      const candidate = path.join(dir, name);
      if (fs.existsSync(candidate)) return candidate;
    }
  }
  return null;
}

/** One loud skip line per spec when no Chrome binary exists. */
export function skipWithoutChrome(): void {
  test.skip(
    chromeBinary() == null,
    'no Chrome binary (looked at $CHROME_PATH, google-chrome, chromium, '
      + 'chromium-browser) — install Chrome for Testing or export CHROME_PATH',
  );
}

/**
 * The unpacked extension's pinned id — sha256 over the manifest "key"'s
 * DER SPKI, first 16 bytes hex, digits mapped a-p (Chrome's GenerateId;
 * same algorithm as chrome_driver.dart, so key and id cannot drift apart
 * silently).
 */
export function extensionId(): string {
  const src = fs.readFileSync(path.join(extDir, 'manifest.json'), 'utf8');
  const json = JSON.parse(src.replace(/^\s*\/\/.*$/gm, '')) as { key: string };
  const hex = createHash('sha256')
    .update(Buffer.from(json.key, 'base64'))
    .digest('hex');
  return hex
    .slice(0, 32)
    .split('')
    .map((c) => String.fromCharCode(0x61 + parseInt(c, 16)))
    .join('');
}

/**
 * Whether build_browser_ext.sh --with-app left a real fa app bundle in
 * panel/app/ (gitignored, so lean checkouts say false). panel.js keys its
 * redirect on exactly this file — tests must too, not on FA_E2E_WITH_APP
 * (a local --with-app build without the env var still redirects).
 */
export const appBundlePresent = fs.existsSync(
  path.join(extDir, 'panel', 'app', 'index.html'),
);

/**
 * Waits out panel.js's app-hosting decision (issue #152): the HEAD probe
 * fires AFTER goto() resolved, and with an app bundle it navigates via
 * location.replace — any evaluate in flight then dies with "Execution
 * context was destroyed, most likely because of a navigation". Waiting for
 * the final URL once here settles the page for every later eval. Without
 * the bundle the probe keeps panel.html; nothing to wait for.
 */
export async function awaitPanelSettled(page: Page): Promise<void> {
  if (!appBundlePresent) return;
  await page.waitForURL('**/panel/app/index.html', { timeout: 30_000 });
}

/** Tiny loopback static server for test/browser_ext/fixture/. */
export class FixtureServer {
  private server: http.Server | null = null;
  private boundPort = 0;

  get url(): string {
    return `http://127.0.0.1:${this.boundPort}/`;
  }

  start(): Promise<void> {
    const { promise, resolve } = Promise.withResolvers<void>();
    this.server = http.createServer((req, res) => {
      const rel = (req.url ?? '/').split('?')[0];
      // Contain to fixtureRoot (CodeQL js/path-injection): resolve kills
      // ".." segments, then the prefix check refuses anything that escaped
      // the root — this loopback server is test-only, but the check is
      // cheap and keeps the security gate green without a dismissal.
      const file = path.resolve(
        fixtureRoot,
        rel === '/' ? 'index.html' : `.${rel}`,
      );
      if (!file.startsWith(fixtureRoot + path.sep)) {
        res.statusCode = 403;
        res.end();
        return;
      }
      fs.readFile(file, (err, data) => {
        if (err) {
          res.statusCode = 404;
          res.end();
          return;
        }
        res.setHeader(
          'content-type',
          file.endsWith('.js')
            ? 'text/javascript; charset=utf-8'
            : 'text/html; charset=utf-8',
        );
        res.end(data);
      });
    });
    this.server.listen(0, '127.0.0.1', () => {
      this.boundPort = (this.server!.address() as { port: number }).port;
      resolve();
    });
    return promise;
  }

  stop(): Promise<void> {
    const { promise, resolve } = Promise.withResolvers<void>();
    this.server?.close(() => resolve());
    this.server = null;
    return promise;
  }
}

