    expect(service.messages.where((m) => m.role == 'system'), isEmpty);
    expect(
      service.messages.where(
        (m) => m.role == 'user' && m.content == '[from peer-1] mid-run hello',
      ),
      hasLength(1),
    );
    addTearDown(channel.close);
  });

