        'approval_request' => ApprovalRequestMsg(
          id: event['id'] as String? ?? '',
          call: event['call'] is Map
              ? Map<String, dynamic>.from(event['call'] as Map)
              : const <String, dynamic>{},
          reason: event['reason'] as String? ?? '',
        ),
        _ => StreamMsg(event: event),
