/// invisibility amplifier (#320 AC4). Mid-run: queued for steering at
/// the next step boundary with a pending indicator (AC3).
Future<void> _routeOne(String from, String text) async {
  if (!_booted) {
    _preBootMail.add((from: from, text: text));
    _emitStatus();
