  String get kind => 'hello_ack';

  @override
  Map<String, dynamic> encode() => {
    'kind': kind,
    'protoVersion': protoVersion,
    'serverCapabilities': serverCapabilities,
    'sessionId': sessionId,
  };
}

/// UI → SW: adopt [sessionId], or a fresh session when null. `lastEventId`
