  // 'fa-ui-v2' (SW UI port server); the canvas renders nothing a DOM
  // probe can read, so the test adopts the app's own wire: a probe port
  // on the panel page collects the exact envelopes the app renders from.
  await fa.panel.evaluate(() => {
    const w = window as unknown as {
      __faProbe: { msgs: unknown[] };
      chrome: { runtime: { connect(ci: { name: string }): { onMessage: { addListener(cb: (m: unknown) => void): void };
    };
    const probe = { msgs: [] as unknown[] };
    const port = w.chrome.runtime.connect({ name: 'fa-ui-v2' });
    port.onMessage.addListener((m) => probe.msgs.push(m));
    w.__faProbe = probe;
  });
  const probeMsgs = () =>
    fa.panel.evaluate(() => (window as unknown as { __faProbe: { msgs: Record<string, unknown>[] }).__faProbe.msgs);

